'use strict';
nav.splice(5,0,['empire','06','Maktrådet']);
nav.forEach((n,i)=>n[1]=String(i+1).padStart(2,'0'));
const beforeEmpireRender=render,beforeEmpireHome=home,beforeEmpireEvent=eventPanel;
const projectMeter=o=>`<div class="project-progress"><b>${o.progress} / ${o.need} måloppgjør</b>${meter(o.progress/o.need*100)}<p>${Math.max(0,o.due-s.week)} uker til fristen. Fremdrift krever at målene oppfylles; tiden alene fullfører ingenting.</p></div>`;
let projectScope=null;
function projectScopeSelector(){const list=G.availableProjects(s),scopes=[...new Set(list.map(q=>q.city?String(q.city):'national'))];if(!scopes.includes(projectScope))projectScope=scopes[0];return scopes.length?`<label class="project-scope">VELG BY ELLER NASJONALT PROSJEKT<select id="projectScope">${scopes.map(c=>`<option value="${c}" ${projectScope===c?'selected':''}>${c==='national'?'Nasjonale avtaler og etterfølgelse':G.CITIES[+c].name}</option>`).join('')}</select></label>`:'';}
function visibleProjects(){return G.availableProjects(s).filter(q=>(q.city?String(q.city):'national')===projectScope);}
function empire(){const e=s.empire,open=s.rankLevel>=3;
 return `<div class="page-title"><div><span class="section-kicker">MAKTRÅDET / ${e.decisions} AVGJØRELSER / ${e.successes} PROSJEKTER</span><h1>DU E FERDIG<br>MED SMÅJOBBANE.</h1><p>Velg hvordan makten skal fordeles. Lederne følger prosjektene og vareflyten; du bestemmer hvem som får marginen, tryggheten og siste ord.</p></div><span class="rubber-stamp">${open?'BAKMANNENS BORD':'ÅPNER SOM BAKMANN'}</span></div>
 <section class="council-strip"><span>Neste maktråd <b>${open?Math.max(0,e.nextCouncil-s.week)+' uker':'Etter Bakmann og to byer'}</b></span><span>Lokale maktavtaler <b>${Object.keys(e.charters).length} / 4</b></span><span>Resultater <b>${e.successes} fullført · ${e.setbacks} tilbakeslag</b></span></section>
 <section class="active-project"><h2>La lederne håndtere hverdagen.</h2><p>Med Bakmann-rang og to ledere tar diskret beredskap søkelyset tilbake til 48 når det når 55. Koster 2,5 % av ukas rutebrutto og automatiske bruttosalg, minst 2 000 kr per inngrep. Alt føres i regnskapet.</p><div class="market-actions">${btn('responsePolicy','discreet',e.response!=='manual'?'Diskret beredskap ✓':'Deleger beredskap',!open,'button ghost')}${btn('responsePolicy','manual',e.response==='manual'?'Egen oppfølging ✓':'Følg opp selv',!open,'button ghost')}</div></section><h2 class="section-heading">Kem får bestemme?</h2><div class="doctrine-grid">${G.DOCTRINES.map(d=>`<article class="council-card ${e.doctrine===d.id?'chosen':''}"><span class="section-kicker">STYRINGSFORM / ${e.doctrine===d.id?'VALGT':'VALGBAR'}</span><h2>${d.name}</h2><p>${d.text}</p>${btn('doctrine',d.id,e.doctrine===d.id?'Valgt ✓':'Velg '+d.name,!open||e.doctrine===d.id,'button ghost')}</article>`).join('')}</div><p class="rule-note">Første valg er gratis. Bytte krever 13 uker, koster 10 innflytelse og −4 lojalitet. Ruteoversikten viser pris og risiko etter gjeldende avtaler.</p>
 <h2 class="section-heading">Bygg et apparat som tåler deg.</h2><div class="doctrine-grid">${G.INSTITUTIONS.map(i=>{const n=e.institutions[i.id]||0,cost=Math.round(i.cost*Math.pow(2,n));return `<article class="council-card"><span class="section-kicker">INSTITUSJON / NIVÅ ${n} AV 3</span><h2>${i.name}</h2><p>${i.text}</p><p class="small">Fast drift 1 500 kr / uke per nivå. Krever to ledere og 20 innflytelse; bruker 8.</p>${btn('institution',i.id,n===3?'Fullt utviklet':'Utvikle · '+kr(cost),!open||n===3||s.cash<cost||s.influence<20||s.managers<2,'button brass')}</article>`;}).join('')}</div>
 <h2 class="section-heading">Et prosjekt. Et faktisk mål.</h2>${e.operation?`<section class="active-project"><span class="section-kicker">LEDERNE FØLGER OPP AUTOMATISK</span><h2>${esc(e.operation.title)}</h2><p>${esc(e.operation.text)}</p>${projectMeter(e.operation)}${btn('abandonProject','','Avslutt prosjektet…',false,'text-button')}</section>`:`${projectScopeSelector()}<div class="project-grid">${visibleProjects().map(q=>`<article class="council-card"><span class="section-kicker">${q.kind==='charter'?G.CITIES[q.city].name+' / '+(q.path==='partnership'?'PARTNERSKAP':'EGEN KONTROLL'):q.kind==='contest'?'RIVALISERING':'ARVEN / NASJONALT PROSJEKT'}</span><h2>${esc(q.title)}</h2><p>${esc(q.text)}</p><p class="small">${G.projectReady(s,q)?'Grunnlaget er på plass.':'Bygg forutsetningene i prosjektmålet før fristen.'} ${q.duration} ukers frist · ${kr(q.cost)} · krever 15 innflytelse og bruker 5. Ved feil: investeringen går tapt, −5 innflytelse og −5 lojalitet. Maktprosjekter koster også folk.</p><button class="button brass" data-project-kind="${q.kind}" data-project-city="${q.city}" data-project-path="${q.path}" ${!open||s.cash<q.cost||s.influence<15?'disabled':''}>Start prosjekt →</button></article>`).join('')||'<div class="empty-state"><h2>Bygg fotfeste før du krever en stol.</h2><p>Lokale prosjekter åpner etter andre bykapittel. Landsavtalen trenger fire byer og tre lokale maktavtaler. Etterfølgerplanen trenger tre byer og Lederskolen.</p></div>'}</div>`}
 <section class="council-requirements"><h2>Gudfar er et nettverk, ikkje en saldo.</h2>${G.godfatherRequirements(s).map(r=>`<p class="${r.ok?'profit':''}">${r.ok?'✓':'○'} ${r.name}</p>`).join('')}<p class="small">Eksisterende Gudfar-rang beholdes i gamle lagringer. Prosjektene og maktrådet fortsetter gjennom resten av kampanjen.</p></section>
 ${e.effects.length?`<section class="active-project"><h2>Avtaler som former ukene nå.</h2>${e.effects.map(f=>`<p>${f.city===null?'Hele nettverket':G.CITIES[f.city].name} · ${f.until-s.week} uker igjen${f.price?' · bruttopris '+Math.round((f.price-1)*100)+' %':''}${f.demand?' · etterspørsel '+Math.round((f.demand-1)*100)+' %':''}${f.risk?' · risiko '+(f.risk*100).toFixed(0)+' prosentpoeng':''}</p>`).join('')}</section>`:''}
 ${e.history.length?`<section class="chapter-list"><h2>Valgene setter spor.</h2>${e.history.slice(0,8).map(h=>`<div class="chapter-row ${h.won?'done':''}"><b>${h.won?'✓':'×'}</b><section><h3>${esc(h.title)}</h3><p>Uke ${h.week} · ${h.progress} / ${h.need} måloppgjør · ${h.won?'Gjennomført':'Fristen eller målet glapp'}</p></section></div>`).join('')}</section>`:''}`;
}
home=function(){const e=s.empire;return beforeEmpireHome()+(s.rankLevel>=3?`<section class="council-home"><div><span class="section-kicker">MAKTRÅDET / DET NESTE STORE VALGET</span><h2>${e.operation?esc(e.operation.title):'Kem skal eie veksten?'}</h2><p>${e.operation?esc(e.operation.text):'Lokale maktavtaler og et lederskap som kan overta gjør nettverket sterkere. Velg et prosjekt; folkene følger opp.'}</p>${e.operation?projectMeter(e.operation):''}</div><button class="button brass" data-view="empire">Til maktrådet →</button></section>`:'');};
eventPanel=function(){if(s.event?.kind!=='empire')return beforeEmpireEvent();const e=G.eventInfo(s);return `<section class="event-paper council-event"><span class="section-kicker">MAKTRÅDET / ${esc(e.speaker)}</span><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="event-choices">${e.choices.map((c,i)=>btn('choice',i,esc(c.name)+`<small>${c.cash?debit(-c.cash):'0 kr'} · ${c.influence>0?'+':''}${c.influence} innflytelse · ${c.loyalty>0?'+':''}${c.loyalty} lojalitet</small><small>${esc(c.detail)}</small>`,s.cash+c.cash<0,'choice')).join('')}</div>${btn('defer','','La saken ligge · +8 lokalt rivalpress',false,'text-button')}</section>`;};
render=function(){const current=view;if(current==='empire')view='legacy';beforeEmpireRender();view=current;if(current==='empire'){$('#screen').innerHTML=empire();$('#nav [aria-current]')?.removeAttribute('aria-current');$('#nav .active')?.classList.remove('active');const tab=$('#nav [data-view="empire"]');tab.classList.add('active');tab.setAttribute('aria-current','page');}};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.projectKind)act('project',{kind:b.dataset.projectKind,city:+b.dataset.projectCity,path:b.dataset.projectPath});});
// Replace the generic destructive project action with a concrete consequence dialog.
document.addEventListener('click',e=>{const b=e.target.closest('[data-act="abandonProject"]');if(!b)return;e.stopImmediatePropagation();e.preventDefault();modal('<h2>Avslutte prosjektet?</h2><p>Investeringen refunderes ikke. Du mister 5 innflytelse og 5 lojalitet. Maktprosjekter koster også folk.</p><button class="button danger-button" id="abandonConfirmed">Avslutt prosjektet</button><button class="button ghost" id="keepProject">Fortsett prosjektet</button>');$('#abandonConfirmed').onclick=()=>{act('abandonProject');$('#dialog').close();};$('#keepProject').onclick=()=>$('#dialog').close();},true);
render();

document.addEventListener('change',e=>{if(e.target.id==='projectScope'){projectScope=e.target.value;render();$('#projectScope').scrollIntoView({block:'center'});}});
